		{
			std::set<Assembly*>::iterator it;
			for (it = assemblies.begin(); it != assemblies.end(); ++it)
			{
				cleanAssembly(*it);
			}
			assemblies.clear();

			while (edges.size() != 0)
			{
				std::set<Edge*>::iterator e = edges.begin();
				cleanEdge(*e);
				(*e)->setInEdgeList(false);
