	void TreeStage::onEdgeRemovingNonJoint(Edge* e)
	{
		if (e->downstreamOfStage(this))
		{
			static_cast<IWorldStage*>(getDownstream())->onEdgeRemoving(e);
		}
		Edge* value = e;
		if (e->getInEdgeList())
		{
			edges.erase(value);
			e->setInEdgeList(false);
		}
	}
