    const std::string& file = ServiceProvider::create<ContentProvider>(&getContext(thread))->getFile(id);
    if (luaL_loadfile(thread, file.c_str()) != 0) lua_error(thread);
    lua_call(thread, 0, LUA_MULTRET);
    return lua_gettop(thread) - top;
